<?php
declare(strict_types=1);
require_once '../includes/security.php';
secureSessionStart();
requireRole(['admin']);
require_once '../config/database.php';
require_once '../includes/audit.php';

if (!isset($pdo)) {
    die('Database connection failed.');
}
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrfToken();$id=(int)($_POST['job_id']??0);$action=(string)($_POST['action']??'');if($action==='retry'){$stmt=$pdo->prepare("UPDATE grading_jobs SET status='queued',attempts=0,available_at=NOW(),locked_at=NULL,worker_token=NULL,started_at=NULL,completed_at=NULL,error_message=NULL WHERE id=? AND status='failed'");$stmt->execute([$id]);writeAuditLog($pdo,'grading_job.retried','grading_job',$id);$_SESSION['success']=$stmt->rowCount()?'Đã đưa tác vụ vào hàng đợi.':'Tác vụ không còn ở trạng thái lỗi.';}elseif($action==='cancel'){$timeout=max(60,(int)envValue('AI_GRADE_QUEUE_TIMEOUT_SECONDS','300'));$stmt=$pdo->prepare("UPDATE grading_jobs SET status='cancelled',completed_at=NOW(),worker_token=NULL,error_message='Admin đã hủy tác vụ.' WHERE id=? AND (status='queued' OR (status='processing' AND started_at<DATE_SUB(NOW(),INTERVAL {$timeout} SECOND)))");$stmt->execute([$id]);writeAuditLog($pdo,'grading_job.cancelled','grading_job',$id);$_SESSION['success']=$stmt->rowCount()?'Đã hủy tác vụ.':'Chỉ có thể hủy tác vụ đang chờ hoặc bị treo.';}header('Location: ai_grading.php');exit;}
$stats=$pdo->query("SELECT SUM(status='queued') queued,SUM(status='processing') processing,SUM(status='failed') failed,SUM(status='completed' AND completed_at>=DATE_SUB(NOW(),INTERVAL 24 HOUR)) completed_24h FROM grading_jobs")->fetch();$comparison=$pdo->query("SELECT COUNT(*) reviews,SUM(ABS(COALESCE(ai_score,0)-final_score)>0.01) changed,COALESCE(ROUND(AVG(ABS(COALESCE(ai_score,0)-final_score)),2),0) avg_difference FROM grading_reviews")->fetch();$jobs=$pdo->query("SELECT gj.*,a.title assignment_title,u.name student_name,TIMESTAMPDIFF(MINUTE,COALESCE(gj.started_at,gj.created_at),NOW()) age_minutes FROM grading_jobs gj LEFT JOIN assignments a ON a.id=gj.assignment_id LEFT JOIN users u ON u.id=gj.student_id WHERE gj.status IN ('queued','processing','failed') ORDER BY FIELD(gj.status,'failed','processing','queued'),gj.id DESC LIMIT 200")->fetchAll();$reviews=$pdo->query("SELECT gr.*,a.title assignment_title,student.name student_name,reviewer.name reviewer_name FROM grading_reviews gr JOIN submissions s ON s.id=gr.submission_id JOIN assignments a ON a.id=s.assignment_id JOIN users student ON student.id=s.student_id JOIN users reviewer ON reviewer.id=gr.reviewed_by ORDER BY gr.reviewed_at DESC LIMIT 100")->fetchAll();$page_title='Giám sát chấm AI';require_once '../includes/header.php';
?>
<style>.ai-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:20px}.ai-stat{padding:18px;background:var(--glass-bg);border:1px solid var(--border-color);border-radius:14px}.ai-stat strong{display:block;font-size:30px}.ai-table{width:100%;border-collapse:collapse;min-width:900px}.ai-table th,.ai-table td{padding:11px;border-bottom:1px solid var(--border-color);text-align:left}.ai-error{max-width:360px;color:var(--danger);overflow-wrap:anywhere}@media(max-width:800px){.ai-stats{grid-template-columns:1fr 1fr}}</style><h1><i class='bx bx-bot'></i> Giám sát chấm AI</h1><?php if(isset($_SESSION['success'])):?><div class="alert alert-success"><?php echo htmlspecialchars($_SESSION['success']);unset($_SESSION['success']);?></div><?php endif;?><div class="ai-stats"><div class="ai-stat"><strong><?php echo (int)$stats['queued'];?></strong>Đang chờ</div><div class="ai-stat"><strong><?php echo (int)$stats['processing'];?></strong>Đang xử lý</div><div class="ai-stat"><strong style="color:var(--danger)"><?php echo (int)$stats['failed'];?></strong>Thất bại</div><div class="ai-stat"><strong style="color:var(--success)"><?php echo (int)$stats['completed_24h'];?></strong>Hoàn tất 24 giờ</div></div><div class="box" style="margin-bottom:20px"><h2>Độ lệch AI và giáo viên</h2><p><strong><?php echo (int)$comparison['changed'];?>/<?php echo (int)$comparison['reviews'];?></strong> lượt được giáo viên thay đổi điểm · Độ lệch trung bình <strong><?php echo $comparison['avg_difference'];?></strong> điểm.</p></div><div class="box" style="margin-bottom:20px"><h2>Hàng đợi cần xử lý</h2><div style="overflow:auto"><table class="ai-table"><thead><tr><th>Mã</th><th>Bài / học viên</th><th>Trạng thái</th><th>Tuổi</th><th>Lỗi</th><th>Thao tác</th></tr></thead><tbody><?php foreach($jobs as $job):?><tr><td>#<?php echo $job['id'];?></td><td><strong><?php echo htmlspecialchars($job['assignment_title']??'Đã xóa');?></strong><small style="display:block"><?php echo htmlspecialchars($job['student_name']??'');?></small></td><td><?php echo htmlspecialchars($job['status']);?></td><td><?php echo (int)$job['age_minutes'];?> phút</td><td class="ai-error"><?php echo htmlspecialchars(mb_strimwidth((string)($job['error_message']??''),0,180,'…','UTF-8'));?></td><td><form method="post" style="display:flex;gap:6px"><?php echo csrfField();?><input type="hidden" name="job_id" value="<?php echo $job['id'];?>"><?php if($job['status']==='failed'):?><button class="btn btn-primary" name="action" value="retry">Chạy lại</button><?php endif;?><button class="btn btn-outline" name="action" value="cancel">Hủy</button></form></td></tr><?php endforeach;?><?php if(!$jobs):?><tr><td colspan="6">Hàng đợi đang sạch.</td></tr><?php endif;?></tbody></table></div></div><div class="box"><h2>Lịch sử đối chiếu điểm</h2><div style="overflow:auto"><table class="ai-table"><thead><tr><th>Thời gian</th><th>Bài / học viên</th><th>Điểm AI</th><th>Điểm giáo viên</th><th>Chênh lệch</th><th>Người duyệt</th></tr></thead><tbody><?php foreach($reviews as $r):?><tr><td><?php echo date('d/m/Y H:i',strtotime($r['reviewed_at']));?></td><td><?php echo htmlspecialchars($r['assignment_title'].' · '.$r['student_name']);?></td><td><?php echo $r['ai_score']??'—';?></td><td><strong><?php echo $r['final_score'];?></strong></td><td><?php echo number_format(abs((float)$r['final_score']-(float)$r['ai_score']),2);?></td><td><?php echo htmlspecialchars($r['reviewer_name']);?></td></tr><?php endforeach;?></tbody></table></div></div><?php require_once '../includes/footer.php';?>
